'use client'

import * as React from 'react'
import VisuallyHidden from '@radui/ui/VisuallyHidden'

import './card-stack.css'

export type CardStackProps = {
    /** The cards, front to back. */
    cards: React.ReactNode[]
    /** Accessible name for the stack. */
    label: string
    /** How many cards peek out behind the front one. */
    visibleBehind?: number
    className?: string
}

// A deck you page through with Previous / Next. Only the front card is reachable
// by screen readers and Tab; the position is announced politely on change.
const CardStack = ({ cards, label, visibleBehind = 2, className }: CardStackProps) => {
    const [front, setFront] = React.useState(0)
    const [leaving, setLeaving] = React.useState<number | null>(null)
    const count = cards.length

    const go = (step: 1 | -1) => {
        if (step === 1) setLeaving(front)
        setFront((current) => (current + step + count) % count)
    }

    return <section className={['rad-fx-stack', className].filter(Boolean).join(' ')} aria-label={label} aria-roledescription="card stack">
        <div className="rad-fx-stack-deck">
            {cards.map((card, i) => {
                const position = (i - front + count) % count
                const isFront = position === 0
                return <div
                    key={i}
                    className="rad-fx-stack-card"
                    data-position={position}
                    data-leaving={leaving === i ? '' : undefined}
                    onAnimationEnd={() => setLeaving(null)}
                    inert={!isFront}
                    aria-hidden={!isFront || undefined}
                    style={{
                        '--rad-fx-stack-pos': Math.min(position, visibleBehind + 1),
                        zIndex: count - position,
                        opacity: position > visibleBehind ? 0 : 1
                    } as React.CSSProperties}
                >
                    {card}
                </div>
            })}
        </div>
        <div className="rad-fx-stack-controls">
            <button type="button" onClick={() => go(-1)}>Previous</button>
            <span aria-hidden="true">{front + 1} / {count}</span>
            <button type="button" onClick={() => go(1)}>Next</button>
        </div>
        <VisuallyHidden asChild><span aria-live="polite">Card {front + 1} of {count}</span></VisuallyHidden>
    </section>
}

export default CardStack

.rad-fx-stack {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 18px;
}

.rad-fx-stack-deck {
    display: grid;
}

.rad-fx-stack-card {
    grid-area: 1 / 1;
    transform: translateY(calc(var(--rad-fx-stack-pos, 0) * -12px)) scale(calc(1 - var(--rad-fx-stack-pos, 0) * 0.06));
    transform-origin: 50% 0;
    filter: brightness(calc(1 - var(--rad-fx-stack-pos, 0) * 0.15));
    transition: transform 450ms cubic-bezier(0.2, 0.8, 0.2, 1), opacity 300ms ease, filter 300ms ease;
}

/* The card that was just dismissed flies off before settling at the back. */
.rad-fx-stack-card[data-leaving] {
    animation: rad-fx-stack-leave 450ms cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes rad-fx-stack-leave {
    0% { transform: translate(0, 0) rotate(0deg); z-index: 99; }
    45% { transform: translate(115%, -10px) rotate(10deg); z-index: 99; }
    100% { transform: translateY(calc(var(--rad-fx-stack-pos, 0) * -12px)) scale(calc(1 - var(--rad-fx-stack-pos, 0) * 0.06)); }
}

.rad-fx-stack-controls {
    display: flex;
    align-items: center;
    gap: 12px;
    font-variant-numeric: tabular-nums;
}

.rad-fx-stack-controls button {
    padding: 6px 14px;
    border: 1px solid currentcolor;
    border-radius: 999px;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
}

.rad-fx-stack-controls button:focus-visible { outline: 2px solid currentcolor; outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-stack-card { transition: none; }
    .rad-fx-stack-card[data-leaving] { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-stack-card { transition: none; }
[data-rad-fx-motion='reduce'] .rad-fx-stack-card[data-leaving] { animation: none; }
